/* TASK-L188. Nothing is read until a request arrives; then, in order, the staff
   list (for a learner with no coach recorded), the site, the key, and the mail. */
if (Inputs.request !== undefined && Inputs.request !== null) Outputs.go();

/*
 * TELL THE OTHER PERSON A MESSAGE ARRIVED (TASK-L188). THE ONE OWNER OF MESSAGE
 * MAIL: who it goes to, whether they may be emailed, the signed link that stops
 * it, the words, and the send. Nothing else in the template sends mail; the
 * backend sends sign-in links itself and they never pass through here.
 *
 * WHO. A learner's question goes to the coach recorded on their profile
 * (`coachEmail`, written by addLearner). With nobody recorded it goes to EVERY
 * staff account, and that mail says so — never to a guess from history (the
 * product's L132). A coach's reply goes to the learner it belongs to.
 *
 * MAY WE (the product's canEmail, L54), per recipient: an account that has asked
 * not to be emailed (`emailOptOutAt`) or has no address gets nothing. This is the
 * ONE gate; tools/check-opt-out.mjs runs this script and fails if an opted-out
 * recipient is ever handed to the mailer.
 *
 * WHAT IT CARRIES (sprint 54 §2.4): the ONE turn that triggered it and a link —
 * never the thread. The subject never quotes the message: a subject is the
 * most-previewed and most-forwarded part of a mail and shows on a lock screen.
 * The learner is named by the name on their account, else their address, and
 * NEVER by the coach's private label (L84).
 *
 * THE LINKS are built on SITE_ORIGIN, the deployment's configured address, and
 * never on the request's headers: a learner's request must not be able to aim
 * the link in their coach's mail anywhere (requestOrigin.ts). Each mail carries
 * its recipient's own one-click unsubscribe link, signed with UNSUBSCRIBE_KEY
 * over 'dbt-unsubscribe:v1:' + account — the string `unsubscribe` verifies.
 *
 * A MAIL NEVER FAILS A WRITE. This runs after the turn is saved and always
 * answers `done`; a refusal or a dead relay is logged with ids and a count —
 * never an address and never a body (the product's L132).
 *
 * THE SEND is the backend's mailer (`_noodl_send_email`, the seam the Send Email
 * node itself calls), from this script rather than through that node, because
 * a node sends one mail per Do and the staff fallback is one mail PER recipient,
 * each with its own gate and its own unsubscribe link — a loop a graph cannot
 * draw. Recorded as a NodeGX core row in sprint 54's index.
 */
if (Inputs.request !== undefined && Inputs.request !== null) {
  (async () => {
    const r = Inputs.request || {};
    const tag = '[dbt:Message mail] ' + String(r.to || '-') + ' learner=' + String(r.learnerId || '-');
    let sent = 0, skipped = 0, failed = 0;
    try {
      const q = (c, where, limit) => Noodl.Records.query(c, where, { limit: limit || 100, plain: true });
      const one = async (c, where) => (await q(c, where, 2))[0] || null;
      const origin = String(Inputs.origin || '').replace(/\/+$/, '');
      const key = String(Inputs.key || '');
      if (!/^https?:\/\/[^/]+$/.test(origin) || !key) {
        console.error(tag + ' not sent: SITE_ORIGIN or UNSUBSCRIBE_KEY is not provisioned (tools/setup-mail.mjs)');
        Outputs.sent = 0;
        Outputs.done();
        return;
      }
      const send = typeof globalThis._noodl_send_email === 'function' ? globalThis._noodl_send_email : null;
      if (!send) throw new Error('no mailer in this process');

      const hex = (buf) => Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, '0')).join('');
      const hmacKey = await crypto.subtle.importKey('raw', new TextEncoder().encode(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
      const unsubscribeFor = async (userId) =>
        origin + '/unsubscribe?u=' + encodeURIComponent(userId) + '&s=' + hex(await crypto.subtle.sign('HMAC', hmacKey, new TextEncoder().encode('dbt-unsubscribe:v1:' + userId)));

      const learnerId = String(r.learnerId || '');
      const profile = learnerId ? await one('LearnerProfile', { learnerId: { equalTo: learnerId } }) : null;
      if (!profile) throw new Error('no learner profile');
      const learnerUser = profile.userId ? await one('_User', { objectId: { equalTo: profile.userId } }) : null;
      const first = learnerUser && learnerUser.firstName ? String(learnerUser.firstName).trim() : '';
      const last = learnerUser && learnerUser.lastName ? String(learnerUser.lastName).trim() : '';
      const learnerName = (first + ' ' + last).trim() || (learnerUser && learnerUser.email) || 'One of your learners';

      // WHAT IT IS ABOUT, in words: the card's own title where there is one.
      const kind = String(r.anchorKind || '');
      const ref = String(r.anchorId || '').slice(kind.length + 1);
      let about = { lesson: 'a lesson', session: 'a session', evaluation: 'a review', assignment: 'a brief', submission: 'something they sent in', message: 'a message', signal: 'a moment on their course' }[kind] || 'their course';
      try {
        if (kind === 'lesson') { const c = await one('Concept', { conceptId: { equalTo: ref } }); if (c && c.title) about = 'the lesson “' + c.title + '”'; }
        if (kind === 'session') { const s = await one('CoachingSession', { sessionId: { equalTo: ref } }); if (s && s.title) about = 'the session “' + s.title + '”'; }
        if (kind === 'assignment') { const a = await one('Assignment', { assignmentId: { equalTo: ref } }); if (a && a.title) about = 'the brief “' + a.title + '”'; }
      } catch (e) { /* the noun is enough */ }

      // WHO.
      let recipients = [];
      let unassigned = false;
      if (r.to === 'coach') {
        const coachEmail = String(profile.coachEmail || '').trim().toLowerCase();
        const coach = coachEmail ? await one('_User', { username: { equalTo: coachEmail } }) : null;
        if (coach) recipients = [coach];
        else {
          unassigned = true;
          const ids = Array.isArray(Inputs.staffIds) ? Inputs.staffIds : [];
          for (const id of ids) { const u = await one('_User', { objectId: { equalTo: String(id) } }); if (u) recipients.push(u); }
        }
      } else if (r.to === 'learner') {
        if (learnerUser) recipients = [learnerUser];
      } else {
        throw new Error('to must be coach or learner');
      }

      const body = String(r.body || '');
      for (const u of recipients) {
        // THE GATE.
        const address = typeof u.email === 'string' && /@/.test(u.email) ? u.email : '';
        if (!address || u.emailOptOutAt) { skipped++; continue; }
        const unsubscribe = await unsubscribeFor(u.objectId);
        let subject, text;
        if (r.to === 'coach') {
          const link = origin + '/learner?learner=' + encodeURIComponent(learnerId);
          subject = learnerName + ' asked you a question';
          text = [
            learnerName + ' asked you a question about ' + about + ':',
            '',
            body,
            '',
            'Open their programme to reply: ' + link,
            unassigned ? '\nNobody is set as this learner’s coach, so this went to everyone on the staff list.' : '',
            '',
            '—',
            'Replies to this email are not read. Answer on the course, and they will see it there.',
            'Stop emails about messages: ' + unsubscribe,
            'Your sign-in links are not affected.'
          ].join('\n');
        } else {
          const link = origin + '/course?comment=' + encodeURIComponent(String(r.anchorId || ''));
          subject = 'Your coach replied';
          text = [
            'Your coach replied about ' + about + ':',
            '',
            body,
            '',
            'See it on your course: ' + link,
            '',
            '—',
            'Replies to this email are not read. Answer on the course, and your coach will see it there.',
            'Stop emails about messages: ' + unsubscribe,
            'Your sign-in links are not affected.'
          ].join('\n');
        }
        const res = await send({ to: address, subject, text });
        if (res && res.success) sent++;
        else { failed++; console.error(tag + ' a send failed: recipient=' + u.objectId + ' ' + String((res && res.error) || '').slice(0, 160).replace(/[^\s]+@[^\s]+/g, '<address>')); }
      }
      console.log(tag + ' sent=' + sent + ' skipped=' + skipped + ' failed=' + failed + (unassigned ? ' (no coach recorded: staff list)' : ''));
    } catch (e) {
      console.error(tag + ' not sent: ' + String((e && e.message) || e));
    }
    Outputs.sent = sent;
    Outputs.done();
  })();
}
